n X) A B psi := by +  unfold consistencyDefect +  let f : X → ℝ := fun x => +    ∑ a : Alpha, ∑ b : Alpha, +      if a = b then 0 else +        (inner ℂ psi ((EuclideanSpace.equiv I ℂ).symm +          ((A x a * B x b).mulVec psi))).re +  change avgOver (uniformDistribution Gamma) (fun sample => f (e sample).1) = +    avgOver (uniformDistribution X) f +  exact avgOver_uniform_equiv_fst e f + +/-- The consistency defect of Alice's and Bob's completed axis-line readouts +on the common direct-game sample. Failed evaluation remains `none`. -/ +noncomputable def axisSameLineEvaluationDefect +    (lines : ExtendedLinesWitness setting points deltaL) : ℝ := +  consistencyDefect (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (fun sample answer => +      (DistanceCalculus.leftPlacedMeasurement +        (ιB := setting.ExpandedLocalSpace .bob) +        ((answerMeasurement lines .alice +          (.aline, directLdMap P.extendedDirectLd .aline sample)).postprocess +            (axisGameRead sample))).effect answer) +    (fun sample answer => +      (DistanceCalculus.rightPlacedMeasurement +        (ιA := setting.ExpandedLocalSpace .alice) +        ((answerMeasurement lines .bob +          (.aline, directLdMap P.extendedDirectLd .aline sample)).postprocess +            (axisGameRead sample))).effect answer) +    (pairState setting) + +/-- The consistency defect of Alice's and Bob's completed diagonal-line +readouts on the common direct-game sample. Failed evaluation remains `none`. -/ +noncomputable def diagonalSameLineEvaluationDefect +    (lines : ExtendedLinesWitness setting points deltaL) : ℝ := +  consistencyDefect (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (fun sample answer => +      (DistanceCalculus.leftPlacedMeasurement +        (ιB := setting.ExpandedLocalSpace .bob) +        ((answerMeasurement lines .alice +          (.dline, directLdMap P.extendedDirectLd .dline sample)).postprocess +            (diagonalGameRead sample))).effect answ