moved. -/ +private theorem axis_bob_none_mass_at_le_rejectedMass +    (lines : ExtendedLinesWitness setting points deltaL) +    (sample : DirectLdSpace P.extendedDirectLd) : +    bobEventWeight (strategy lines) +        (.aline, directLdMap P.extendedDirectLd .aline sample) +        (fun answer => axisGameRead sample answer = none) ≤ +      directRejectedMass P.extendedDirectLd (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (.aline, directLdMap P.extendedDirectLd .aline sample) := by +  calc +    _ = outcomeEventWeight (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (.aline, directLdMap P.extendedDirectLd .aline sample) +        (fun _ answerB => axisGameRead sample answerB = none) := +      (outcome_event_weight_right_eq _ _ _ _).symm +    _ = outcomeEventWeight (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (.aline, directLdMap P.extendedDirectLd .aline sample) +        (fun answerA answerB => pointGameRead answerA ≠ none ∧ +          axisGameRead sample answerB = none) := +      bob_line_none_event_eq_point_some lines .aline sample (axisGameRead sample) +    _ ≤ outcomeEventWeight (strategy lines) +        (.point, directLdMap P.extendedDirectLd .point sample) +        (.aline, directLdMap P.extendedDirectLd .aline sample) +        (fun answerA answerB => pointGameRead answerA ≠ axisGameRead sample answerB) := by +      apply outcome_event_weight_mono +      intro answerA answerB hnone heq +      exact hnone.1 (heq.trans hnone.2) +    _ = _ := (point_axis_rejectedMass_eq_read_mismatch lines sample).symm + +/-- At a fixed sample, Bob's failed completed diagonal evaluation is +contained in the point/diagonal-line rejection event after zero-mass invalid tags are removed. -/ +private theorem diagonal_bob_none_mass_at_le_rejectedMass +    (lines : ExtendedLinesWitness setting points deltaL) +    (sample : DirectLdSpace P.extendedDirectLd) : +